def weight_init(module, weight_init_algo, size):
    if weight_init_algo == 'normal':
        w =  module.weight.data.cpu().numpy()
        non_zero_weights =  w[np.nonzero(w)] 
        if len(non_zero_weights) > 0:
            weights= np.random.normal(float(np.mean(non_zero_weights)), float(np.std(non_zero_weights)), size = size)
        else: # Fallback if no non-zero weights exist yet
            weights = np.random.normal(0, 0.01, size = size) 
    elif weight_init_algo == 'uniform':  
            weights = np.random.uniform(float(torch.min(module.weight.data)), float(torch.max(module.weight.data)), size = size)
    elif weight_init_algo == 'zero':
            weights = np.zeros(size) 
    else:
        raise Exception('Undefined weight init algorithm: {}'.format(weight_init_algo)) 
    return weights

def get_w_masks(model):
    w_masks = []
    for module in model.modules():
        if isinstance(module, torch.nn.Linear) or isinstance(module, torch.nn.Conv2d):
            weight_mask, bias_mask = module.get_mask()
            w_masks.append(copy.deepcopy(weight_mask).cpu().numpy())
    return w_masks

def get_possible_connections(model, all_units, stable_indices, activations,  grow_algo = 'forwardT_most_active', num_connections = 0):
    if grow_algo == 'full_random':
        return full_random(model, all_units, stable_indices)
    elif  grow_algo =='forwardT_random':
        return forwardT_random(model, all_units, stable_indices)
    elif  grow_algo =='flow_random':
        return flow_random(model, all_units, stable_indices)
    elif grow_algo == 'progressive_rewiring': # NISPA-Replay specific
        # Progressive rewiring defined in NISPA_Replay/NISPA/grow.py
        pass # Actual call is outside this generic function
    else:
        raise Exception('Undefined growth algorithm: {}'.format(grow_algo)) 

def grow_connection_A2B(model, num_connections, all_units, stable_indices, activations,  grow_algo = 'forwardT_most_active',  weight_init_algo = 'zero'):
    if sum(num_connections) == 0:
        return model, num_connections
    # The original get_possible_connections function in NISPA/NISPA/grow.py does not take num_connections
    # but the one in NISPA_Replay/NISPA/grow.py does, which is used for 'progressive_rewiring'.
    # This part should ideally differentiate between NISPA and NISPA-Replay's grow.py.
    # For this consolidated code, assume NISPA_Replay's `get_possible_connections` is used for `progressive_rewiring`.
    possible_connections, bias_matrices = get_possible_connections(model, all_units, stable_indices, activations, grow_algo, num_connections) # Passed num_connections for progressive_rewiring
    layer_id = 0 
    remainder_connections = []
    for module in model.modules():
        if isinstance(module, torch.nn.Linear) or isinstance(module, torch.nn.Conv2d):
            if num_connections[layer_id] == 0:
                remainder_connections.append(0)
                layer_id = layer_id + 1 
                continue
            weight_mask, bias_mask = module.get_mask()
            # Determine the shape for a single connection (kernel size for conv, 1 for linear)
            conn_type = np.ones((possible_connections[layer_id].shape[2], possible_connections[layer_id].shape[3])) if len(possible_connections[layer_id].shape) == 4 else 1
            conn_size = (possible_connections[layer_id].shape[2] * possible_connections[layer_id].shape[3]) if len(possible_connections[layer_id].shape) == 4 else 1

            if len(possible_connections[layer_id].shape) == 4:
                grow_indices_flat = np.nonzero(np.sum(possible_connections[layer_id], axis = (2 , 3))) # Flattened indices (output_unit, input_unit)
            else:
                grow_indices_flat = np.nonzero(possible_connections[layer_id]) # Flattened indices (output_unit, input_unit)

            if len(grow_indices_flat[0]) == 0:
                remainder_connections.append(num_connections[layer_id]) # No possible connections to grow
                layer_id += 1
                continue

            # Calculate how many actual connections (units-to-units) can be grown
            num_possible_unit_connections = len(grow_indices_flat[0])
            num_to_grow_unit_connections = int(num_connections[layer_id] / conn_size)

            selected_unit_indices = []
            if num_to_grow_unit_connections >= num_possible_unit_connections: # Can accommodate all possible
                selected_unit_indices = list(range(num_possible_unit_connections))
                remainder_connections.append(num_connections[layer_id] - num_possible_unit_connections * conn_size)
            else:
                # Sample `num_to_grow_unit_connections` from possible connections
                probs = bias_matrices[layer_id][grow_indices_flat] # Bias for selection
                if np.sum(probs) > 0:
                    selection = np.random.choice(num_possible_unit_connections, size = num_to_grow_unit_connections, replace = False, p = probs / np.sum(probs))
                else:
                    selection = np.random.choice(num_possible_unit_connections, size = num_to_grow_unit_connections, replace = False)
                selected_unit_indices = selection.tolist()
                remainder_connections.append(0)

            # Apply the selected connections
            if selected_unit_indices:
                grow_indices_final = (grow_indices_flat[0][selected_unit_indices], grow_indices_flat[1][selected_unit_indices])
                # Initialize weights for new connections
                init_weights = weight_init(module, weight_init_algo, (len(selected_unit_indices), *possible_connections[layer_id].shape[2:]) if len(possible_connections[layer_id].shape) == 4 else len(selected_unit_indices))

                # Update weight mask and actual weights
                weight_mask[grow_indices_final] = torch.tensor(conn_type, dtype = weight_mask.dtype).to(DEVICE) # Assuming conn_type is scalar or correct shape
                module.weight.data[grow_indices_final] = torch.tensor(init_weights, dtype = torch.float32).to(DEVICE)

            module.set_mask(weight_mask, bias_mask)
            layer_id += 1

    return model, remainder_connections

