class Cycle:
    def __init__(self, loader):
        self.loader = loader
        self.generator = iter(loader)

    def get_batch(self):
        try:
            return next(self.generator)
        except:
            self.generator = iter(self.loader)
            return next(self.generator)

def reset_frozen_gradients_replay(network, freeze_masks): # Renamed to avoid conflict
    mask_index = 0
    l = list(network.modules())[1:-1] # Skip the final layer (output layer) to not freeze its weights

    for module in l:
        if isinstance(module, nn.Linear) or  isinstance(module, nn.Conv2d):
            module.weight.grad[freeze_masks[mask_index][0]] = 0
            module.bias.grad[freeze_masks[mask_index][1]] = 0
            mask_index += 1
    return network

def training_CL_memory(network, loss, optimizer, train_loader, memo_loader, test_loader,  args, epochs, freeze_masks = None):
    if memo_loader is not None:
        memo_loader_cycle = Cycle(memo_loader)  

    if freeze_masks is not None:
        freeze_masks = [(torch.tensor(w).to(torch.bool).to(DEVICE) , torch.tensor(b).to(torch.bool).to(DEVICE)) for w, b in freeze_masks]
    accuracy1 = []

    for epoch in range(epochs):
        network.train()
        train_loss = 0
        for batch_idx, (data, target, *_) in enumerate(train_loader):
            optimizer.zero_grad()
            output = network(data)

            if memo_loader is not None:
                data_memo, target_memo =  memo_loader_cycle.get_batch()
                output_memo = network(data_memo.to(DEVICE))
                l1 = loss(output, target.long())
                l2 = loss(output_memo, target_memo.to(DEVICE).long())
                batch_loss = l1  + args.replay_lambda *  l2
            else:
                batch_loss = loss(output, target.long())

            train_loss += batch_loss.item() * data.size(0)
            batch_loss.backward()
            if freeze_masks is not None:
                network = reset_frozen_gradients_replay(network, freeze_masks) # Using replay-specific reset
            optimizer.step()

        # Test function from NISPA_Replay/NISPA/training.py (simpler test without total loss/top5 etc.)
        _, acc1, _ = test(network, loss, test_loader, current_classes = None, report=True)
        accuracy1.append(acc1)

    return copy.deepcopy(network), [], [], accuracy1 # Modified to match original training_CL return format for consistency

